struct Frame { char name[24]; };
void decode(const unsigned char *wire, size_t size, Frame &out) {
  if (size < 6) return;
  unsigned length = wire[4] | (unsigned(wire[5]) << 8);
  if (length > size - 6) return;
  memcpy(out.name, wire + 6, length);
}

struct Frame { char name[24]; };
void decode(const unsigned char *wire, size_t size, Frame &out) {
  if (size < 6) return;
  unsigned length = wire[4] | (unsigned(wire[5]) << 8);
  if (length > size - 6 || length > sizeof(out.name)) return;
  memcpy(out.name, wire + 6, length);
}

